-- 629: Original BrillaPrep flashcards, batch flashcard-decks-sprint3-001, part 1 of 3.
-- Curriculum-aligned revision content; not official WAEC or NaCCA material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_01', 'deck_sys_topic_biochemistry', 'Name the three main classes of carbohydrates and give one example of each.', 'Monosaccharides (e.g. glucose), disaccharides (e.g. sucrose and maltose) and polysaccharides (e.g. starch, glycogen and cellulose).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_02', 'deck_sys_topic_biochemistry', 'Describe the iodine test for starch and state the positive result.', 'Add a few drops of brown iodine solution to the sample; if starch is present the colour changes from yellow-brown to blue-black.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_03', 'deck_sys_topic_biochemistry', 'Describe the Benedict’s test for a reducing sugar and state the positive result.', 'Heat the solution with blue Benedict’s solution; a reducing sugar reduces the copper(II) ions to copper(I) oxide, giving a brick-red precipitate (through green and orange as the sugar concentration rises).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_04', 'deck_sys_topic_biochemistry', 'What are the monomers of proteins, and what bond joins them?', 'Amino acids, joined by peptide bonds in condensation reactions to form polypeptide chains.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_05', 'deck_sys_topic_biochemistry', 'Describe the Biuret test for protein and state the positive result.', 'Add sodium hydroxide solution, then a few drops of dilute copper(II) sulphate solution; a purple (violet) colour indicates that protein is present.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_06', 'deck_sys_topic_biochemistry', 'What type of reaction builds biological polymers from monomers, and what small molecule is eliminated?', 'Condensation: each new bond formed between monomers eliminates one molecule of water. The reverse process, hydrolysis, adds water to break polymers back into monomers.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_07', 'deck_sys_topic_biochemistry', 'What is an enzyme, and what is it made of?', 'A biological catalyst that speeds up metabolic reactions without being used up or changed; enzymes are proteins folded into a specific three-dimensional shape with an active site.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_08', 'deck_sys_topic_biochemistry', 'Explain enzyme specificity using the lock-and-key model.', 'Only a substrate whose shape is complementary to the enzyme’s active site can bind and react, just as only the correct key fits a lock; this is why each enzyme catalyses one reaction or a small group of related reactions.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_09', 'deck_sys_topic_biochemistry', 'Name four factors that affect the rate of an enzyme-catalysed reaction.', 'Temperature, pH, substrate concentration and enzyme concentration. (Where present, inhibitors also reduce the rate.)', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_10', 'deck_sys_topic_biochemistry', 'What happens to most enzymes well above their optimum temperature, and why?', 'They are denatured: the bonds holding the protein’s shape break, the active site changes shape and the substrate can no longer bind, so the rate falls sharply. Denaturation is usually permanent, unlike the temporary slowing at low temperature.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_11', 'deck_sys_topic_biochemistry', 'Describe the emulsion test for lipids and state the positive result.', 'Dissolve the sample in ethanol, then pour the ethanol solution into water; a cloudy white emulsion forms if lipid is present. (Sudan III stain, which colours lipids red, is an alternative test.)', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_biochemistry_12', 'deck_sys_topic_biochemistry', 'Write the word equation for the hydrolysis of maltose and name the bond broken.', 'Maltose + water → glucose + glucose. Hydrolysis adds a water molecule to break the glycosidic bond linking the two glucose units of the disaccharide.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_01', 'deck_sys_topic_calculus', 'What does the derivative dy/dx of a function represent?', 'The rate of change of y with respect to x; geometrically, the gradient of the tangent to the curve y = f(x) at each point.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_02', 'deck_sys_topic_calculus', 'State the power rule for differentiating xⁿ with respect to x.', 'd/dx(xⁿ) = nxⁿ⁻¹: multiply by the power and reduce the power by one.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_03', 'deck_sys_topic_calculus', 'Differentiate y = 3x² + 5x − 7 with respect to x.', 'dy/dx = 6x + 5. Differentiate term by term: 3x² → 6x, 5x → 5, and the constant −7 → 0.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_04', 'deck_sys_topic_calculus', 'What is the derivative of a constant, and why?', 'Zero. A constant does not change as x changes, so its rate of change is 0; graphically its graph is a horizontal line with gradient 0.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_05', 'deck_sys_topic_calculus', 'Write the definition of the derivative f′(x) from first principles.', 'f′(x) = lim(h→0) [f(x + h) − f(x)]/h — the limiting value of the gradient of the chord as the step h shrinks to zero.', NULL, NULL, 4);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_06', 'deck_sys_topic_calculus', 'How do you locate the stationary (turning) points of y = f(x)?', 'Solve dy/dx = 0 to find the x-values where the gradient is zero, then substitute back into the original equation for the corresponding y-values.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_07', 'deck_sys_topic_calculus', 'How does the sign of the second derivative classify a stationary point?', 'If d²y/dx² > 0 at the stationary point it is a minimum; if d²y/dx² < 0 it is a maximum; if d²y/dx² = 0 the test is inconclusive (the point may be a point of inflexion).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_08', 'deck_sys_topic_calculus', 'State the power rule for integration, ∫xⁿ dx where n ≠ −1.', 'xⁿ⁺¹/(n + 1) + c: increase the power by one, divide by the new power, and add the constant of integration.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_09', 'deck_sys_topic_calculus', 'Why does an indefinite integral include the constant of integration c?', 'Because differentiation destroys constants: infinitely many functions differing only by a constant share the same derivative, so the reverse operation must allow for any constant.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_10', 'deck_sys_topic_calculus', 'What does the definite integral ∫ₐᵇ f(x) dx represent when f(x) ≥ 0?', 'The area enclosed between the curve y = f(x), the x-axis and the vertical lines x = a and x = b.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_11', 'deck_sys_topic_calculus', 'Evaluate ∫₀² 3x² dx.', '[x³]₀² = 2³ − 0³ = 8 − 0 = 8. Integrate 3x² to x³, substitute the upper and lower limits and subtract.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_calculus_12', 'deck_sys_topic_calculus', 'A particle moves with displacement s = 2t³ − 9t² + 12t metres. What is its velocity at t = 1 s?', 'v = ds/dt = 6t² − 18t + 12; at t = 1, v = 6 − 18 + 12 = 0 m/s — the particle is momentarily at rest.', NULL, 'Velocity is the derivative of displacement with respect to time.', 3);
